using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Diagnostics;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
public static class WorkbenchTests {
 static void Check(bool v,string text){if(!v)throw new Exception(text);Console.WriteLine("PASS "+text);}
 static void Pump(Func<bool> done){var frame=new DispatcherFrame();var watch=Stopwatch.StartNew();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(15)};timer.Tick+=(s,e)=>{if(done()||watch.Elapsed.TotalSeconds>10){timer.Stop();frame.Continue=false;}};timer.Start();Dispatcher.PushFrame(frame);Check(done(),"async files loaded");}
 public static int Run(string folder){SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());Directory.CreateDirectory(folder);string sample=Path.Combine(folder,"sample-files");Directory.CreateDirectory(sample);File.WriteAllText(Path.Combine(sample,"train.py"),"print('hello')");File.WriteAllText(Path.Combine(sample,"README.txt"),"AQServer UI fixture");Directory.CreateDirectory(Path.Combine(sample,"checkpoints"));var window=new MonitorWindow(true,new ArchiveStore(Path.Combine(folder,"history")));window.ChooseServer(Storage.LocalServer());window.SetMetrics(Program.Fixture("none"),false);window.SwitchView("文件");window.FileView.Navigate(Path.GetFullPath(sample),true,true);Pump(()=>window.FileView.CurrentPath==Path.GetFullPath(sample));var view=window.FileView;
 foreach(string theme in Theme.Keys){var settings=window.CompactOptions.Copy();settings.ThemeName=theme;window.ApplyOptions(settings);window.SwitchView("文件");window.FileView.Navigate(Path.GetFullPath(sample),true,true);Pump(()=>!window.FileView.IsLoading&&window.FileView.CurrentPath==Path.GetFullPath(sample)&&window.FileView.VisibleEntryCount==3);Check(object.ReferenceEquals(view,window.FileView),"theme preserves file workspace");foreach(var column in view.FilesTable.Columns){var background=(System.Windows.Media.SolidColorBrush)column.HeaderStyle.Setters.OfType<Setter>().First(x=>x.Property==Control.BackgroundProperty).Value;Check(background.Color==Theme.Surface.Color,"all file headers follow theme: "+column.Header);}foreach(int width in new[]{760,1200}){window.RenderImage(Path.Combine(folder,theme+"-files-"+width+".png"),width,width==760?560:900,120);UiReview.Record(window.Root,Path.Combine(folder,theme+"-files-"+width+"-geometry.csv"),"files "+theme+" "+width);Check(window.Audit().Count==0,"toolbar geometry "+theme+" "+width);Check(window.FileView.ActualHeight<=window.Workspace.ActualHeight+1,"files bounded by workspace");}}
 window.SwitchView("GPU");var metrics=Program.Fixture("eight");window.SetMetrics(metrics);var time=DateTime.UtcNow.AddMinutes(-1);window.ArchiveRepository.Append(Storage.LocalServer(),ArchiveRecord.From(metrics,time,5));window.SwitchView("历史");var panel=window.ArchiveView;var data=window.ArchiveRepository.Query(Storage.LocalServer(),time.AddSeconds(-1),time.AddSeconds(1),CancellationToken.None);panel.SetResult(data);panel.SetMetric("GPU");Pump(()=>!panel.SnapshotLoading&&panel.DisplayedRecord!=null);panel.ModuleLayout.IsEditing=true;panel.ModuleLayout.Move("process",0);Snapshot.Save(panel.ModuleLayout,Path.Combine(folder,"history-layout-edit.png"),1120,1100,120,null);panel.ModuleLayout.ClearValue(FrameworkElement.WidthProperty);panel.ModuleLayout.ClearValue(FrameworkElement.HeightProperty);panel.ModuleLayout.IsEditing=false;window.RenderImage(Path.Combine(folder,"history-gpu-snapshot.png"),1200,1000,120);window.Scroll.ScrollToBottom();window.RenderImage(Path.Combine(folder,"history-gpu-processes.png"),1200,1000,120);Check(panel.DisplayedProcessCount==metrics.Processes.Count,"real history UI process count");window.Exit();File.WriteAllText(Path.Combine(folder,"workbench-results.txt"),"ALL PASS: file navigation, theme preservation, 8 full product screenshots, bounded workspace, equal toolbar, readonly historical process count\n");return 0;}
}
